/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// </summary>
internal final class METTMSEngineSalesOrderProccess_PackingSlip extends METTMSEngineSalesOrderProccess
{
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
public void new(METSalesOrderShipmentLoadHeader  _salesOrderShipmentLoadHeader)
{
    salesOrderShipmentLoadHeader = _salesOrderShipmentLoadHeader;
}

/// <summary>
/// Retrieve the METTMSShipmentOrderTable record based on the TMS engine delivery note posting logic
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(SalesIdBase _salesId, WMSPickingRouteID _pickingRouteId = '')
{
    METTMSShipmentOrderTable TMSShipmentOrderTable;

    // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID = PickListID that this order is being added to
    TMSShipmentOrderTable = super(_salesId, _pickingRouteId);

    if (!TMSShipmentOrderTable)
    {
        // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID is blank (order had only been processed at creation, and something went wrong at SO Extraction)
        TMSShipmentOrderTable = super(_salesId, METConstants::emptyString);
    }

    return TMSShipmentOrderTable;
}

/// <summary>
/// Run the TMS engine
/// </summary>
public void run()
{
    METSalesOrderShipmentLoadLines  salesOrderShipmentLoadLines;
    SalesTable                      salesTableLoop;
    METTMSShipmentTable             tmsShipmentTable;
    METTMSShipmentTable             tmsShipmentTableCancel;
    METTMSShipmentOrderTable        tmsShipmentOrderTable;

    // For each combination of sales order - picking list number in the F&O finalisation shipment lines
    while select salesOrderShipmentLoadLines
        group by ShipmentId, OrderNum, PickingListNum
            join salesTableLoop            
           where salesOrderShipmentLoadLines.ShipmentId == salesOrderShipmentLoadHeader.ShipmentId
              && salesTableLoop.SalesId == salesOrderShipmentLoadLines.OrderNum
    {
        this.init(salesTableLoop);

        // Step 1: check if order should be excluded from TMS Engine processing
        // Apply the exact same checks on the sales order being processed as done in “Step 1” of the CB624 FSD’s processing
        if (this.validate())
        {
            proccessLinesTmp = this.initTmpTable();
            try
            {
                ttsbegin;

                // Step 2: heck to see if there is a TSO with PickListID or blank
                tmsShipmentOrderTable = this.getTMSShipmentOrderTable(salesOrderShipmentLoadLines.OrderNum, salesOrderShipmentLoadLines.PickingListNum);

                //Step 2: Check if the order is already on a shipment
                /*if (!tmsShipmentOrderTable.RecId)
                {
                    //Step 3: If order is not on any existing shipment
                    tmsShipmentTable = this.initTMSShipment();

                    //Step 3a: check if there is an existing shipment this order can be made part of.
                    if (!tmsShipmentTable.RecId)
                    {
                        this.createShipment();
                    }
                    else
                    {
                        //Step 3c: If a shipment exists, update it
                        this.createShipment(false);
                    }
                }
                else
                {
                    tmsShipmentTable = this.initTMSShipment();
                    //Step 4: If order is on an existing shipment and there is a change to either Route or Ship date
                    if (tmsShipmentOrderTable.ShipmentId != shipmentId)
                    {
                        //Step 4a: Get the “TMS Shipment” record related to the “TMS Shipment Order”
                        tmsShipmentTableCancel = METTMSShipmentTable::find(tmsShipmentOrderTable.ShipmentId);

                        //Step 4c: Update the current “TMS Shipment” - cancel it
                        this.cancelShipment(salesTable.SalesId);

                        //Step 4d: Link the sales order to a new shipment
                        this.createShipment();

                    }
                    else
                    {
                        //Step 5: If order is on an existing shipment and there is no change to both Route and Ship date
                        //delete Shipment itemgroup - recreate
                        delete_from tmsShipmentOrderTable
                        where tmsShipmentOrderTable.ShipmentId == shipmentId;
                        //Step 3d: Create TMS Shipment Order record
                        //Step 4d: Link the sales order to a new shipment
                        this.createShipment(false);
                    }
                }

                //Step 6: Update order and shipment totals
                //Step 6a: Update the order’s “Order weight”
                //Step 6b: Update the order’s “Order volume”
                //Step 6c: Update order’s “Pallet Total footprint”
                this.updateTMSShipmentOrder();

                //Step 6d: Update the shipment’s “Pallet lifts”
                this.updateTMSShipment();
                */
                ttscommit;
            }
            catch (Exception::Error)
            {
                //An error occurs during the creation or updates of the staging records
                error(strFmt("@MET:TMSEngineSalesOrderProcessCreation", salesTable.SalesId));
            }
        }
    }
}
